package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TypeBindings_toString_TriageGen0Test {

    @Test
    public void testToString_EmptyBindings() {
        // Test the branch: if (_types.length == 0)
        TypeBindings bindings = TypeBindings.emptyBindings();
        assertEquals("<>", bindings.toString());
    }

    @Test
    public void testToString_SingleType() {
        // Test the loop with length 1
        JavaType mockType1 = mock(JavaType.class);
        when(mockType1.getGenericSignature()).thenReturn("String");

        TypeBindings bindings = TypeBindings.create(Object.class, mockType1);

        assertEquals("<String>", bindings.toString());
    }

    @Test
    public void testToString_MultipleTypes() {
        // Test the branch: if (i > 0) to ensure commas are added correctly
        JavaType mockType1 = mock(JavaType.class);
        JavaType mockType2 = mock(JavaType.class);
        JavaType mockType3 = mock(JavaType.class);

        when(mockType1.getGenericSignature()).thenReturn("Integer");
        when(mockType2.getGenericSignature()).thenReturn("Boolean");
        when(mockType3.getGenericSignature()).thenReturn("Double");

        TypeBindings bindings = TypeBindings.create(Object.class, new JavaType[]{mockType1, mockType2, mockType3});

        assertEquals("<Integer,Boolean,Double>", bindings.toString());
    }

    @Test
    public void testToString_WithComplexSignatures() {
        // Test with signatures containing special characters
        JavaType mockType1 = mock(JavaType.class);
        JavaType mockType2 = mock(JavaType.class);

        when(mockType1.getGenericSignature()).thenReturn("List<String>");
        when(mockType2.getGenericSignature()).thenReturn("Map<String, Integer>");

        TypeBindings bindings = TypeBindings.create(Object.class, mockType1, mockType2);

        assertEquals("<List<String>,Map<String, Integer>>", bindings.toString());
    }
}
